// This should work only for absolute and fixed positions
export function getTBLRValues({ placement, position }) {
  if (position === 'relative') return {}

  const style = { position }

  if (placement === 'top' || placement === 'bottom') {
    style.insetInline = 0
  }

  if (placement === 'left' || placement === 'right') {
    style.insetBlock = 0
  }

  if (placement === 'top') style.insetBlockStart = 0
  if (placement === 'bottom') style.insetBlockEnd = 0
  if (placement === 'left') style.insetInlineStart = 0
  if (placement === 'right') style.insetInlineEnd = 0
  return style
}
